contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, address other) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(other != address(this));
        require(address(this).balance >= amount);

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        require(balBefore == amount);
        require(address(c).balance >= balBefore);

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(!reverted && c.getBalance(address(this)) == 0);
    }

    receive() external payable {}
}

